const body = $input.first().json.body || $input.first().json || {};
const appUrl = String($env.EXPORTFLOW_APP_URL || 'https://exportflow-lovat.vercel.app').replace(/\/+$/, '');
const campaignId = body.campaign_id || body.campaignId;
if (!campaignId) throw new Error('campaign_id is required.');
const secret = $env.N8N_OUTREACH_WEBHOOK_SECRET || $env.N8N_WEBHOOK_SECRET || '';
return [{ json: { appUrl, campaign_id: campaignId, secret, gemini_key: $env.GEMINI_API_KEY || '', gemini_model: $env.GEMINI_MODEL || 'gemini-3-flash-preview' } }];

const cfg = $('Prepare Generate Request').first().json;
const context = $input.first().json;
if (!cfg.gemini_key) throw new Error('Missing GEMINI_API_KEY in n8n environment.');
const leads = Array.isArray(context.leads) ? context.leads : [];
if (leads.length === 0) throw new Error('Campaign has no leads.');
const prompt = [
  'You are writing production B2B cold outreach for ExportFlow.',
  'Return JSON only. No markdown fences.',
  'Required schema: {"campaign_summary": string, "sequences": [{"lead_id": string, "company_name": string, "contact_name": string, "email": string, "website": string, "approval_summary": string, "personalization_evidence": string[], "initial": {"subject": string, "body_text": string}, "followup_1": {"subject": string, "body_text": string}, "followup_2": {"subject": string, "body_text": string}, "safety_notes": string[] }], "global_safety_notes": string[] }',
  'Write a different sequence for every lead. Follow-ups must reference the initial email naturally and must not sound automated.',
  'Use receiver personal name when available. Use website/evidence only; do not invent facts.',
  'Keep each email short, human, specific, and plain-text friendly. No spammy claims, no fake urgency, no attachments, no tracking language.',
  'Include the user CTA and signature only if present in context. Preserve compliance fields from context.',
  'If a lead has weak evidence, mention only safe observable facts or keep personalization light.',
  '',
  `Context JSON: ${JSON.stringify(context)}`
].join('\n');
return [{ json: { ...cfg, context, prompt } }];

const cfg = $('Build Gemini Sequence Prompt').first().json;
const payload = $input.first().json;
const text = payload?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const cleaned = String(text).replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
let generated;
try {
  generated = JSON.parse(cleaned);
} catch (error) {
  generated = { campaign_summary: 'Gemini returned non-JSON output.', sequences: [], raw_text: text, parse_error: String(error?.message || error) };
}
if (!Array.isArray(generated.sequences)) generated.sequences = [];
return [{ json: { appUrl: cfg.appUrl, secret: cfg.secret, campaign_id: cfg.campaign_id, generated, context: cfg.context } }];

const body = $input.first().json.body || $input.first().json || {};
const appUrl = String($env.EXPORTFLOW_APP_URL || 'https://exportflow-lovat.vercel.app').replace(/\/+$/, '');
const campaignId = body.campaign_id || body.campaignId;
if (!campaignId) throw new Error('campaign_id is required.');
return [{ json: { appUrl, campaign_id: campaignId, secret: $env.N8N_OUTREACH_WEBHOOK_SECRET || $env.N8N_WEBHOOK_SECRET || '' } }];

const prep = $('Prepare Due Messages Request').first().json;
const payload = $input.first().json || {};
const messages = Array.isArray(payload.messages) ? payload.messages : [];
return messages.map((message) => ({ json: { ...message, appUrl: prep.appUrl, secret: prep.secret, notify_on_send: prep.notify_on_send } }));

const sentItems = $input.all();
const dueItems = $('Split Due Messages').all();
return sentItems.map((sent, index) => {
  const due = dueItems[index]?.json || {};
  const response = sent.json || {};
  const status = response.status || (response.ok || response.success ? 'sent' : 'failed');
  const success = status === 'sent' || status === 'test_sent' || Boolean(response.ok || response.success);
  return {
    json: {
      appUrl: due.appUrl,
      secret: due.secret,
      campaign_id: due.campaign_id,
      lead_id: due.lead_id,
      message_id: due.message_id || due.id,
      step: due.step,
      status,
      success,
      sent_at: response.sent_at || new Date().toISOString(),
      gmail_message_id: response.gmail_message_id || null,
      gmail_thread_id: response.gmail_thread_id || null,
      to_email: response.to_email || due.lead?.email || null,
      original_to_email: response.original_to_email || due.lead?.original_email || due.lead?.email || null,
      subject: response.subject || null,
      body_html: response.body_html || null,
      body_text: response.body_text || null,
      generated: response.generated || {},
      error: response.error || response.message || null
    }
  };
});

const appUrl = String($env.EXPORTFLOW_APP_URL || 'https://exportflow-lovat.vercel.app').replace(/\/+$/, '');
const secret = $env.N8N_OUTREACH_WEBHOOK_SECRET || $env.N8N_WEBHOOK_SECRET || '';
return [
  { json: { appUrl, secret, step: 'followup_1', after_days: Number($env.EXPORTFLOW_FOLLOWUP_1_DAYS || 3) } },
  { json: { appUrl, secret, step: 'followup_2', after_days: Number($env.EXPORTFLOW_FOLLOWUP_2_DAYS || 7) } }
];
